--- a/tests/terminal-status.test.ts
+++ b/tests/terminal-status.test.ts
@@ -0,0 +1,43 @@
+import { test } from "node:test";
+import assert from "node:assert/strict";
+import {
+  IMPROVEMENT_STATUSES,
+  TERMINAL_STATUSES,
+  isTerminalStatus,
+  type ImprovementStatus,
+} from "../src/core/selfdev/ImprovementQueue";
+
+// Exhaustive: adding a status without deciding here fails typecheck.
+const EXPECTED: Record<ImprovementStatus, boolean> = {
+  Detected: false,
+  Analyzing: false,
+  Proposed: false,
+  Approved: false,
+  "In Development": false,
+  Testing: false,
+  Evaluation: false,
+  Ready: false,
+  Applying: false,
+  Integrated: true,
+  Recorded: true,
+  Failed: false,
+  Blocked: false,
+  Rejected: true,
+  "Rolled Back": true,
+};
+
+test("isTerminalStatus is true exactly for Integrated, Recorded, Rejected and Rolled Back", () => {
+  for (const status of IMPROVEMENT_STATUSES) {
+    assert.equal(isTerminalStatus(status), EXPECTED[status], `status ${status}`);
+  }
+});
+
+test("every status is covered and TERMINAL_STATUSES matches the predicate", () => {
+  assert.deepEqual([...IMPROVEMENT_STATUSES].sort(), (Object.keys(EXPECTED) as ImprovementStatus[]).sort());
+  assert.deepEqual(
+    [...TERMINAL_STATUSES].sort(),
+    IMPROVEMENT_STATUSES.filter((status) => isTerminalStatus(status)).sort(),
+  );
+  assert.equal(TERMINAL_STATUSES.length, 4);
+});
+

